<?php

declare(strict_types=1);

namespace App\Modules\Ares\Domain\Model\Battle\Grid;

/**
 * A fine hex grid partitioned into hexagonal clusters ("super-hexes") of a given radius.
 *
 * The battlefield is a grid of clusters: each cluster is the area of one fleet, and its
 * cells are where squadrons stand. Clusters themselves are addressed with axial
 * coordinates, so that the battlefield and the fleet grids share the same primitives.
 *
 * Hexagons of radius N tile the plane, their centers forming a lattice generated by
 * (2N+1, -N) and (N, N+1) in axial coordinates.
 */
final readonly class ClusteredHexGrid
{
	private Hex $firstBasis;
	private Hex $secondBasis;

	public function __construct(
		public int $clusterRadius,
	) {
		if ($clusterRadius < 0) {
			throw new \InvalidArgumentException('The cluster radius must be positive');
		}

		$this->firstBasis = new Hex(2 * $clusterRadius + 1, -$clusterRadius);
		$this->secondBasis = new Hex($clusterRadius, $clusterRadius + 1);
	}

	public function cellsPerCluster(): int
	{
		return 3 * $this->clusterRadius * ($this->clusterRadius + 1) + 1;
	}

	/**
	 * Fine cell at the center of the given cluster.
	 */
	public function clusterCenter(Hex $cluster): Hex
	{
		return $this->firstBasis->scale($cluster->q)->add($this->secondBasis->scale($cluster->r));
	}

	/**
	 * @return list<Hex>
	 */
	public function clusterCells(Hex $cluster): array
	{
		return $this->clusterCenter($cluster)->range($this->clusterRadius);
	}

	/**
	 * Cluster containing the given fine cell.
	 */
	public function clusterOf(Hex $cell): Hex
	{
		// Solve cell = a * firstBasis + b * secondBasis, then look for the exact cluster around the rounded solution
		$determinant = $this->cellsPerCluster();
		$a = ($cell->q * $this->secondBasis->r - $cell->r * $this->secondBasis->q) / $determinant;
		$b = ($this->firstBasis->q * $cell->r - $this->firstBasis->r * $cell->q) / $determinant;

		for ($da = -1; $da <= 1; ++$da) {
			for ($db = -1; $db <= 1; ++$db) {
				$candidate = new Hex((int) round($a) + $da, (int) round($b) + $db);

				if ($this->clusterCenter($candidate)->distanceTo($cell) <= $this->clusterRadius) {
					return $candidate;
				}
			}
		}

		throw new \LogicException(sprintf('No cluster found for cell %s', $cell->toKey()));
	}
}
